#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace delete_inactive_users {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
  std::optional<sqlgen::DateTime> last_login;
  std::string status = "active";
};

int delete_inactive_users() {
  // Connect to the SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn) {
    return -1; // Connection failed
  }

  // Begin transaction
  auto begin_result = conn->begin_transaction();
  if (!begin_result) {
    return -1; // Failed to begin transaction
  }

  // Delete users who have not logged in since 2025-01-01
  const char* delete_sql = "DELETE FROM User WHERE last_login < DATE('2025-01-01')";
  auto execute_result = conn->execute(delete_sql);
  if (!execute_result) {
    conn->rollback(); // Rollback on error
    return -1;
  }

  // Commit the transaction
  auto commit_result = conn->commit();
  if (!commit_result) {
    conn->rollback(); // Rollback if commit fails
    return -1;
  }

  // Return success (0 indicates successful commit)
  return 0;
}

} // namespace delete_inactive_users
```

This implementation:

1. **Connects to the database**: Uses `sqlgen::sqlite::connect()` to connect to "test_db.sqlite"
2. **Begins a transaction**: Calls `begin_transaction()` to ensure atomicity
3. **Executes the DELETE statement**: Uses the SQL query to delete users with `last_login < DATE('2025-01-01')`
4. **Commits the transaction**: Calls `commit()` to persist the changes
5. **Returns the result**: Returns 0 on success, -1 on any failure
6. **Error handling**: Includes rollback on errors to maintain data integrity

The function follows the pattern shown in the test fragments, using the sqlgen library's connection and transaction management features.

