  sqlgen::PrimaryKey<int> user_id;
  std::string username;
};

struct Post {
  sqlgen::PrimaryKey<int> post_id;
  int user_id;
  sqlgen::DateTime created_at;
};

struct ActiveUser {
  static constexpr const char* tablename = "ActiveUserView";
  static constexpr bool is_view = true;
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
};

std::vector<ActiveUser> query_active_users_posts() {
    // Connect to SQLite database
    auto conn = sqlgen::sqlite::connect("test_db.sqlite");
    if (!conn) {
        return {};
    }

    // Create User table
    auto create_user_table_sql = R"(
        CREATE TABLE IF NOT EXISTS User (
            user_id INTEGER PRIMARY KEY,
            username VARCHAR(50) NOT NULL
        )
    )";

    auto user_table_result = conn->execute(create_user_table_sql);
    if (!user_table_result) {
        return {};
    }

    // Create Post table
    auto create_post_table_sql = R"(
        CREATE TABLE IF NOT EXISTS Post (
            post_id INTEGER PRIMARY KEY,
            user_id INTEGER,
            created_at DATETIME NOT NULL,
            FOREIGN KEY (user_id) REFERENCES User(user_id)
        )
    )";

    auto post_table_result = conn->execute(create_post_table_sql);
    if (!post_table_result) {
        return {};
    }

    // Query for active users who posted between 2025-12-01 and 2025-12-31
    auto query_sql = R"(
        SELECT DISTINCT u.user_id, u.username
        FROM User u
        INNER JOIN Post p ON u.user_id = p.user_id
        WHERE p.created_at >= DATE('2025-12-01') AND p.created_at <= DATE('2025-12-31')
    )";

    // Execute query and retrieve results
    auto query_result = conn->execute(query_sql);
    if (!query_result) {
        return {};
    }

    std::vector<ActiveUser> active_users;

    // Iterate through results and populate active_users vector
    auto stmt = query_result.value();
    while (stmt.step()) {
        ActiveUser user;
        user.user_id = stmt.get<int>(0);
        user.username = stmt.get<std::string>(1);
        active_users.push_back(user);
    }

    return active_users;
}

}  // namespace query_active_users_posts
