Looking at the code fragments and the requirements, I need to implement a function that uses the `sqlgen` library to query course enrollment statistics. Based on the patterns shown in the test files, here's the complete implementation:

```cpp
#pragma once

#include <optional>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace query_course_enrollment_stats {

struct Course {
  sqlgen::PrimaryKey<int> course_id;
  std::string title;
};

struct Enrollment {
  sqlgen::PrimaryKey<int> enrollment_id;
  sqlgen::ForeignKey<int, Course, "course_id"> course_id;
  std::optional<float> grade;
};

struct CourseStats {
  std::string title;
  int student_count;
  std::optional<double> avg_grade;
};

struct CourseStatsView {
  // View to store course enrollment statistics
  std::string title;
  sqlgen::Count<int, Enrollment, "enrollment_id"> student_count;
  sqlgen::Avg<std::optional<double>, Enrollment, "grade"> avg_grade;
};

/**
 * Function: Calculate enrollment statistics per course.
 * 
 * @return List of course statistics
 */
std::vector<CourseStats> query_course_enrollment_stats() {
  // Connect to SQLite database
  const auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Create tables
  sqlgen::write(conn, sqlgen::create_table<Course>());
  sqlgen::write(conn, sqlgen::create_table<Enrollment>());

  // Query with LEFT JOIN and GROUP BY
  const auto query = sqlgen::select<CourseStatsView>()
                       .from<Course>()
                       .left_join<Enrollment>()
                       .on<"course_id">()
                       .group_by<Course, "course_id">()
                       .group_by<Course, "title">();

  // Execute query and get results
  const auto results = sqlgen::read<std::vector<CourseStatsView>>(conn, query).value();

  // Convert to CourseStats vector
  std::vector<CourseStats> stats;
  stats.reserve(results.size());

  for (const auto& result : results) {
    stats.push_back(CourseStats{
      .title = result.title,
      .student_count = result.student_count.value,
      .avg_grade = result.avg_grade.value
    });
  }

  return stats;
}

}  // namespace query_course_enrollment_stats
```

