 * Function: Calculate daily traffic metrics from a log table.
 * 
 * @return List of daily traffic metrics
 */
std::vector<DailyTraffic> query_daily_traffic_metrics() {
  // Connect to the SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Execute the SQL query to calculate daily traffic metrics
  const char* query_sql = R"(
    SELECT strftime('%Y-%m-%d', visit_time) as visit_date, 
           COUNT(*) as total_visits, 
           COUNT(DISTINCT url) as unique_pages
    FROM PageVisit
    GROUP BY visit_date
    ORDER BY visit_date
  )";

  // Execute the query and get results
  auto result = conn->execute(query_sql);

  // Parse results into DailyTraffic vector
  std::vector<DailyTraffic> daily_metrics;

  if (result) {
    // Iterate through the result set
    for (auto& row : *result) {
      DailyTraffic metric;
      metric.visit_date = row.get<std::string>(0).value_or("");
      metric.total_visits = row.get<int>(1).value_or(0);
      metric.unique_pages = row.get<int>(2).value_or(0);
      daily_metrics.push_back(metric);
    }
  }

  return daily_metrics;
}

