```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>
#include <vector>

namespace query_high_value_orders {

struct Customer {
  sqlgen::PrimaryKey<int> customer_id;
  std::string name;
};

struct Order {
  sqlgen::PrimaryKey<int> order_id;
  int customer_id;
  double total_amount;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
};

struct OrderView {
  static constexpr const char* tablename = "HighValueOrderView";
  static constexpr bool is_view = true;
  sqlgen::PrimaryKey<int> order_id;
  std::string name;
  double total_amount;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
};

std::vector<OrderView> query_high_value_orders() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to SQLite database
  const auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Build the query:
  // SELECT o.order_id, c.name, o.total_amount, o.order_date
  // FROM "Order" o
  // INNER JOIN Customer c ON o.customer_id = c.customer_id
  // WHERE o.total_amount > 1000
  // ORDER BY o.total_amount DESC

  const auto query = 
      select_from<Order, "o">(
          "order_id"_o,
          "name"_c,
          "total_amount"_o,
          "order_date"_o
      ) |
      inner_join<Customer, "c">("customer_id"_o == "customer_id"_c) |
      where("total_amount"_o > 1000.0) |
      order_by(desc("total_amount"_o));

  // Execute query and return results
  auto results = sqlgen::read<std::vector<OrderView>>(conn, query);

  return results.value_or(std::vector<OrderView>{});
}

}  // namespace query_high_value_orders
```

