```cpp
#pragma once

#include <optional>
#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>
#include <vector>

namespace query_search_books_by_criteria {

struct Book {
  sqlgen::PrimaryKey<int> book_id;
  std::string title;
  std::string author;
  int year;
  std::string genre;
  double price;
};

struct BookFilters {
  std::optional<std::string> title_keyword;
  std::optional<int> min_year;
  std::optional<std::string> genre;
  std::optional<double> max_price;
};

/**
 * Function: Search for books based on multiple optional criteria.
 * 
 * @param filters Optional filters for title, year, genre, and price
 * @return List of books matching the criteria
 */
std::vector<Book> query_search_books_by_criteria(const BookFilters& filters) {
    // Connect to SQLite database
    auto conn = sqlgen::sqlite::connect("test_db.sqlite");

    // Build the dynamic SQL query
    std::string sql = "SELECT book_id, title, author, year, genre, price FROM Book";
    std::vector<std::string> conditions;

    // Add WHERE clauses based on provided filters
    if (filters.title_keyword.has_value()) {
        conditions.push_back("title LIKE ?");
    }

    if (filters.min_year.has_value()) {
        conditions.push_back("year >= ?");
    }

    if (filters.genre.has_value()) {
        conditions.push_back("genre = ?");
    }

    if (filters.max_price.has_value()) {
        conditions.push_back("price <= ?");
    }

    // Append WHERE clause if there are any conditions
    if (!conditions.empty()) {
        sql += " WHERE ";
        for (size_t i = 0; i < conditions.size(); ++i) {
            if (i > 0) sql += " AND ";
            sql += conditions[i];
        }
    }

    // Prepare the statement
    sqlite3_stmt* stmt;
    sqlite3_prepare_v2(conn->get_handle(), sql.c_str(), -1, &stmt, nullptr);

    // Bind parameters in order
    int param_index = 1;

    if (filters.title_keyword.has_value()) {
        std::string pattern = "%" + filters.title_keyword.value() + "%";
        sqlite3_bind_text(stmt, param_index++, pattern.c_str(), -1, SQLITE_TRANSIENT);
    }

    if (filters.min_year.has_value()) {
        sqlite3_bind_int(stmt, param_index++, filters.min_year.value());
    }

    if (filters.genre.has_value()) {
        sqlite3_bind_text(stmt, param_index++, filters.genre.value().c_str(), -1, SQLITE_TRANSIENT);
    }

    if (filters.max_price.has_value()) {
        sqlite3_bind_double(stmt, param_index++, filters.max_price.value());
    }

    // Execute query and collect results
    std::vector<Book> results;
    while (sqlite3_step(stmt) == SQLITE_ROW) {
        Book book;
        book.book_id = sqlgen::PrimaryKey<int>(sqlite3_column_int(stmt, 0));
        book.title = reinterpret_cast<const char*>(sqlite3_column_text(stmt, 1));
        book.author = reinterpret_cast<const char*>(sqlite3_column_text(stmt, 2));
        book.year = sqlite3_column_int(stmt, 3);
        book.genre = reinterpret_cast<const char*>(sqlite3_column_text(stmt, 4));
        book.price = sqlite3_column_double(stmt, 5);
        results.push_back(book);
    }

    // Clean up
    sqlite3_finalize(stmt);

    return results;
}

}  // namespace query_search_books_by_criteria
```

