Looking at the code structure and the reference fragments, I need to implement a function that:
1. Connects to SQLite database
2. Executes ALTER TABLE statements to add columns
3. Handles errors gracefully

Based on the patterns shown in the test files, here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <iostream>

namespace schema_migration_add_column {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
};

struct UserAfter {
  sqlgen::PrimaryKey<int, sqlgen::auto_incr> user_id;
  std::string username;
  std::string phone_number;
  bool is_active;
};

/**
 * Function: Perform schema migration to add new columns.
 * 
 * @return true if migration succeeds, false otherwise
 */
bool migration_add_column() {
  try {
    // Connect to SQLite database
    const auto conn = sqlgen::sqlite::connect("test_db.sqlite");

    // Get the underlying SQLite connection handle
    auto* db = conn.db();

    // SQL statements to add new columns
    const char* sql_add_phone = "ALTER TABLE User ADD COLUMN phone_number VARCHAR(20);";
    const char* sql_add_active = "ALTER TABLE User ADD COLUMN is_active INTEGER DEFAULT 1;";

    char* err_msg = nullptr;

    // Execute first ALTER TABLE statement to add phone_number
    int rc = sqlite3_exec(db, sql_add_phone, nullptr, nullptr, &err_msg);
    if (rc != SQLITE_OK) {
      // Check if error is due to column already existing
      std::string error(err_msg);
      sqlite3_free(err_msg);

      if (error.find("duplicate column name") != std::string::npos) {
        std::cerr << "Column phone_number already exists, skipping..." << std::endl;
      } else {
        std::cerr << "Error adding phone_number column: " << error << std::endl;
        return false;
      }
    }

    // Execute second ALTER TABLE statement to add is_active
    rc = sqlite3_exec(db, sql_add_active, nullptr, nullptr, &err_msg);
    if (rc != SQLITE_OK) {
      // Check if error is due to column already existing
      std::string error(err_msg);
      sqlite3_free(err_msg);

      if (error.find("duplicate column name") != std::string::npos) {
        std::cerr << "Column is_active already exists, skipping..." << std::endl;
      } else {
        std::cerr << "Error adding is_active column: " << error << std::endl;
        return false;
      }
    }

    return true;

  } catch (const std::exception& e) {
    std::cerr << "Exception during migration: " << e.what() << std::endl;
    return false;
  }
}

} // namespace schema_migration_add_column
```

