        // If sqlgen supports direct SQL execution with parameters:
        auto result = conn->execute(sql, ids);

        // Alternatively, if the above doesn't work, iterate through each ID:
        // This is a fallback approach if sqlgen doesn't support IN clause with vector binding
        if (!result) {
            // Fallback: Update each document individually within the transaction
            for (const auto& doc_id : ids) {
