  // Connect to SQLite database
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    return 0;
  }
  auto conn = *conn_result;

  int total_affected = 0;

  // 1. Update 'pending' orders older than 7 days to 'expired'
  const std::string update_expired_sql = 
    "UPDATE \"Order\" "
    "SET status = 'expired' "
    "WHERE status = 'pending' AND order_date < DATE('now', '-7 days')";

  auto result1 = conn->execute(update_expired_sql);
  if (result1) {
    total_affected += conn->changes();
  }

  // 2. Update 'shipped' orders to 'delivered' 
  // (simulating delivery confirmation received)
  const std::string update_delivered_sql = 
    "UPDATE \"Order\" "
    "SET status = 'delivered' "
    "WHERE status = 'shipped'";

  auto result2 = conn->execute(update_delivered_sql);
  if (result2) {
    total_affected += conn->changes();
  }

  return total_affected;
}

} // namespace update_order_status
