Looking at the code fragments and the requirements, I need to implement an upsert function using the `sqlgen` library. Based on the examples, I can see that `sqlgen` provides `connect`, `write`, and `execute` functions. For SQLite's `INSERT OR REPLACE`, I'll likely need to use raw SQL execution.

Here's the complete implementation:

```cpp
#pragma once

#include <optional>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>

namespace upsert_user_profile {

struct UserProfile {
  sqlgen::PrimaryKey<int> user_id;
  std::optional<std::string> bio;
  std::optional<std::string> avatar_url;
};

bool upsert_user_profile(const UserProfile& u) {
  // Connect to SQLite database
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    return false;
  }
  auto conn = *conn_result;

  // Prepare the INSERT OR REPLACE statement
  const char* sql = "INSERT OR REPLACE INTO UserProfile (user_id, bio, avatar_url) VALUES (?, ?, ?)";

  // Prepare the statement
  sqlite3_stmt* stmt = nullptr;
  int rc = sqlite3_prepare_v2(
    static_cast<sqlite3*>(conn->get_native_handle()),
    sql,
    -1,
    &stmt,
    nullptr
  );

  if (rc != SQLITE_OK) {
    return false;
  }

  // Bind parameters
  sqlite3_bind_int(stmt, 1, u.user_id.value);

  if (u.bio.has_value()) {
    sqlite3_bind_text(stmt, 2, u.bio->c_str(), -1, SQLITE_TRANSIENT);
  } else {
    sqlite3_bind_null(stmt, 2);
  }

  if (u.avatar_url.has_value()) {
    sqlite3_bind_text(stmt, 3, u.avatar_url->c_str(), -1, SQLITE_TRANSIENT);
  } else {
    sqlite3_bind_null(stmt, 3);
  }

  // Execute the statement
  rc = sqlite3_step(stmt);
  sqlite3_finalize(stmt);

  return (rc == SQLITE_DONE);
}

} // namespace upsert_user_profile
```

