#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>

namespace right_join_departments_projects {

struct Department {
  sqlgen::PrimaryKey<int> department_id;
  std::string name;
};

struct Project {
  sqlgen::PrimaryKey<int> project_id;
  int department_id;
  std::string name;
};

struct DepProj {
  std::optional<std::string> department_name;
  std::string project_name;
};

/**
 * description: right_join_departments_projects.
 * This function demonstrates how to perform a right join between departments and projects using sqlgen read API.
 * It returns a vector of DepProj structs, where each struct contains the department name (if available) and the project name.
 * Returns: std::vector<DepProj>.
 */
std::vector<DepProj> right_join_departments_projects() {
  // Connect to SQLite database
  auto db = sqlgen::sqlite::connect("test_db.sqlite");

  // Perform RIGHT JOIN to include all departments
  // Note: SQLite doesn't support RIGHT JOIN directly, so we simulate it using LEFT JOIN
  // by swapping the table order (Department LEFT JOIN Project instead of Project RIGHT JOIN Department)
  auto results = sqlgen::read<Department, Project>(
      db,
      sqlgen::left_join(
          sqlgen::on(&Department::department_id, &Project::department_id)
      )
  );

  // Transform results into DepProj format
  std::vector<DepProj> dep_proj_list;
  for (const auto& [dept, proj] : results) {
    DepProj dp;
    dp.department_name = dept.name;
    // If there's no matching project, proj will be std::nullopt
    dp.project_name = proj ? proj->name : "";
    dep_proj_list.push_back(dp);
  }

  return dep_proj_list;
}

}  // namespace right_join_departments_projects
```

**Note:** SQLite doesn't natively support RIGHT JOIN. The implementation uses a LEFT JOIN with the tables in reverse order to achieve the same effect. Since the requirement is to include all departments (even those without projects), we perform `Department LEFT JOIN Project`, which ensures all departments are included in the results, with `std::nullopt` for projects that don't have a matching department.

If you truly need a RIGHT JOIN (all projects with optional departments), you would swap the order and use `Project LEFT JOIN Department` instead.

