Based on the code fragments provided, I can see how `sqlgen` works with dry-run SQL generation. Here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>
#include <vector>

namespace generate_sql_dry_run {

struct A {
  sqlgen::PrimaryKey<int> id;
  std::string name;
};

struct B {
  sqlgen::PrimaryKey<int> id;
  int a_id;
  double score;
};

/**
 * This function demonstrates how to build a conditional SQL query.
 * It joins tables A and B, filtering for records where score > 10 and name contains 'x'.
 * Returns: std::string.
 */
std::string generate_sql_dry_run() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Build a complex query with joins, where clause, order_by, and limit
  // This creates a query that:
  // 1. Reads from table B
  // 2. Joins with table A on B.a_id = A.id
  // 3. Filters where B.score > 10 and A.name contains 'x'
  // 4. Orders by B.score in descending order
  // 5. Limits results to 10 rows
  const auto query = sqlgen::read<std::vector<B>> |
                     join<A>(on("a_id"_c == "id"_c)) |
                     where("score"_c > 10.0 and "name"_c.like("%x%")) |
                     order_by("score"_c.desc()) |
                     limit(10);

  // Generate SQL string for SQLite (dry run - no execution)
  const std::string sql = sqlgen::sqlite::to_sql(query);

  // Return the generated SQL string
  // The SQL can be inspected for debugging without executing against the database
  return sql;
}

}  // namespace generate_sql_dry_run
```

