#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace upsert_inventory_items {

struct Inventory {
  sqlgen::PrimaryKey<int> item_id;
  std::string name;
  int quantity;
};

/**
 * description: upsert_inventory_items.
 * This function demonstrates how to use upsert (insert or replace) statements in sqlgen write API.
 * It inserts or replaces the given inventory items in the Inventory table.
 */
bool upsert_inventory_items(const std::vector<Inventory>& items) {
  try {
    // Connect to SQLite database
    auto conn = sqlgen::sqlite::connect("test_db.sqlite");

    if (!conn) {
      return false;
    }

    // Upsert each inventory item (insert or replace)
    for (const auto& item : items) {
      // Use write with replace mode for upsert behavior
      auto write_result = sqlgen::write(*conn, item, sqlgen::WriteMode::Replace);

      if (!write_result) {
        return false;
      }
    }

    // Verify by reading back the items
    auto read_result = sqlgen::read<std::vector<Inventory>>(*conn);

    if (!read_result) {
      return false;
    }

    const auto& stored_items = read_result.value();

    // Verify that all items were upserted correctly
    for (const auto& item : items) {
      bool found = false;
      for (const auto& stored_item : stored_items) {
        if (stored_item.item_id.value() == item.item_id.value() &&
            stored_item.name == item.name &&
            stored_item.quantity == item.quantity) {
          found = true;
          break;
        }
      }
      if (!found) {
        return false;
      }
    }

    return true;
  } catch (...) {
    return false;
  }
}

}  // namespace upsert_inventory_items

