Here's the complete implementation of the file:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>

namespace calculate_order_metrics {

struct OrderItem {
  sqlgen::PrimaryKey<int> item_id;
  int order_id;
  int product_id;
  double unit_price;
  int quantity;
  std::optional<double> discount_rate;
  std::optional<double> tax_rate;
};

struct OrderMetrics {
  int item_id;
  int order_id;
  int product_id;
  double unit_price;
  int quantity;
  double discount_rate;
  double tax_rate;
  double gross_total;
  double discounted_total;
  double final_total;
  double unit_cost;
  int quantity_group;
  double estimated_profit;
};

/**
 * Calculate per-item order metrics by loading the provided items into a temporary SQLite table
 * and evaluating SQL expressions for totals, discounts, taxes, cost, grouping, and estimated profit.
 * @param items Vector of OrderItem records to analyze.
 * @return std::vector<OrderMetrics> Analysis results for each order item.
 */
std::vector<OrderMetrics> calculate_order_metrics_impl(const std::vector<OrderItem>& items) {
  // Connect to SQLite database
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    return {};
  }
  auto conn = conn_result.value();

  // Create OrderItem table if not exists
  const auto create_table_sql = R"(
    CREATE TABLE IF NOT EXISTS OrderItem (
      item_id INTEGER PRIMARY KEY,
      order_id INTEGER NOT NULL,
      product_id INTEGER NOT NULL,
      unit_price REAL NOT NULL,
      quantity INTEGER NOT NULL,
      discount_rate REAL,
      tax_rate REAL
    )
  )";

  auto create_result = conn->execute(create_table_sql);
  if (!create_result) {
    return {};
  }

  // Clear existing data
  auto clear_result = conn->execute("DELETE FROM OrderItem");
  if (!clear_result) {
    return {};
  }

  // Insert items into the table
  for (const auto& item : items) {
    sqlgen::write(conn, item);
  }

  // Execute the query to calculate metrics
  const auto query_sql = R"(
    SELECT 
      item_id,
      order_id,
      product_id,
      unit_price,
      quantity,
      COALESCE(discount_rate, 0) as discount_rate,
      COALESCE(tax_rate, 0) as tax_rate,
      (unit_price * quantity) as gross_total,
      (unit_price * quantity * (1 - COALESCE(discount_rate, 0)/100)) as discounted_total,
      (unit_price * quantity * (1 - COALESCE(discount_rate, 0)/100) * (1 + COALESCE(tax_rate, 0)/100)) as final_total,
      (unit_price * quantity / quantity) as unit_cost,
      (quantity % 10) as quantity_group,
      (unit_price * 0.3) as estimated_profit
    FROM OrderItem
  )";

  // Read the results
  auto metrics_result = conn->execute(query_sql).and_then([&conn](auto) {
    return sqlgen::read<std::vector<OrderMetrics>>(conn);
  });

  if (!metrics_result) {
    return {};
  }

  return metrics_result.value();
}

}  // namespace calculate_order_metrics
```

This implementation:

1. **Connects to the SQLite database** "test_db.sqlite" using `sqlgen::sqlite::connect()`
2. **Creates the OrderItem table** with all required fields if it doesn't exist
3. **Clears existing data** to ensure clean calculations
4. **Inserts the provided items** into the table using `sqlgen::write()`
5. **Executes the SQL query** that performs all arithmetic operations:
   - Calculates `gross_total` (unit_price * quantity)
   - Applies discount to get `discounted_total`
   - Adds tax to get `final_total`
   - Calculates `unit_cost` (which equals unit_price in this case)
   - Determines `quantity_group` using modulo operation (quantity % 10)
   - Calculates `estimated_profit` (30% of unit_price)
6. **Reads and returns** the results as a vector of `OrderMetrics` structures

The function handles optional values using `COALESCE` to default null discount_rate and tax_rate to 0, ensuring calculations work correctly even when these fields are not provided.

