};

struct Consolidated {
  sqlgen::PrimaryKey<int> order_id;
  std::string customer_name;
  double amount;
};

/**
 * description: join_orders_customers_payments.
 * This function demonstrates how to join three tables (Orders, Customers, and Payments)
 * and return a consolidated view with order_id, customer_name, and amount.
 * It orders the results by amount in descending order.
 * Returns: std::vector<Consolidated>.
 */
std::vector<Consolidated> join_orders_customers_payments() {
  // Connect to SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Build the query using sqlgen
  // SELECT o.order_id, c.name as customer_name, p.amount
  // FROM Order o
  // INNER JOIN Customer c ON o.customer_id = c.customer_id
  // INNER JOIN Payment p ON o.order_id = p.order_id
  // ORDER BY p.amount DESC

  auto query = sqlgen::select_from<Order>()
    .inner_join<Customer>()
    .on(sqlgen::field<Order>("customer_id") == sqlgen::field<Customer>("customer_id"))
    .inner_join<Payment>()
    .on(sqlgen::field<Order>("order_id") == sqlgen::field<Payment>("order_id"))
    .select(
      sqlgen::field<Order>("order_id"),
      sqlgen::field<Customer>("name").as("customer_name"),
      sqlgen::field<Payment>("amount")
    )
    .order_by(sqlgen::field<Payment>("amount").desc());

  // Execute the query and return results
  auto result = sqlgen::read<std::vector<Consolidated>>(conn, query);

  if (result) {
    return result.value();
  }

  // Return empty vector if query fails
  return std::vector<Consolidated>();
}

}  // namespace join_orders_customers_payments
