```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace replace_text_in_notes {

struct Note {
  sqlgen::PrimaryKey<int> note_id;
  std::string content;
};

struct UpdatedNote {
  sqlgen::PrimaryKey<int> note_id;
  std::string updated_content;
};

/**
 * description: replace_text_in_notes.
 * This function demonstrates how to replace text in notes using sqlgen update API.
 * It replaces all occurrences of "foo" with "bar" in the content column of the Note table.
 * Returns: std::vector<UpdatedNote>.
 */
std::vector<UpdatedNote> replace_text_in_notes() {
  // Connect to SQLite database
  const auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Read all notes from the Notes table
  const auto notes = sqlgen::read<std::vector<Note>>(conn).value();

  // Vector to store updated notes
  std::vector<UpdatedNote> updated_notes;

  // Process each note and replace "foo" with "bar"
  for (const auto& note : notes) {
    // Create a copy of the note with replaced content
    Note updated_note = note;

    // Replace all occurrences of "foo" with "bar" in the content
    std::string new_content = note.content;
    size_t pos = 0;
    const std::string target = "foo";
    const std::string replacement = "bar";

    while ((pos = new_content.find(target, pos)) != std::string::npos) {
      new_content.replace(pos, target.length(), replacement);
      pos += replacement.length();
    }

    // Update the content in the note
    updated_note.content = new_content;

    // Write the updated note back to the database
    sqlgen::write(conn, updated_note);

    // Add to the result vector
    updated_notes.push_back(UpdatedNote{
      .note_id = note.note_id,
      .updated_content = new_content
    });
  }

  return updated_notes;
}

}  // namespace replace_text_in_notes
