```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace update_set_operations {

struct Account {
  sqlgen::PrimaryKey<int> account_id;
  double balance;
  std::string status;
};

/**
 * description: update_set_operations.
 * This function demonstrates how to use set operations in update statements using sqlgen write API.
 * It returns true if the update operations are successful, and false otherwise.
 * Returns: bool.
 */
bool update_set_operations() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to SQLite database
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    return false;
  }

  // Create Account table (drop if exists first)
  auto conn = conn_result
    .and_then(drop<Account> | if_exists)
    .and_then(create<Account>);

  if (!conn) {
    return false;
  }

  // Insert initial test data
  std::vector<Account> initial_accounts = {
    {.account_id = 1, .balance = 1000.0, .status = "active"},
    {.account_id = 2, .balance = 2000.0, .status = "active"},
    {.account_id = 3, .balance = 1500.0, .status = "inactive"}
  };

  auto write_result = sqlgen::write(conn, initial_accounts);
  if (!write_result) {
    return false;
  }

  // Update balance and status using set operations
  // Update account 1: set balance to 1500.0 and status to "premium"
  auto update_result1 = conn.and_then(
    update<Account>(
      "balance"_c.set(1500.0),
      "status"_c.set("premium")
    ) | where("account_id"_c == 1)
  );

  if (!update_result1) {
    return false;
  }

  // Update account 2: set balance to 2500.0
  auto update_result2 = update_result1.and_then(
    update<Account>("balance"_c.set(2500.0)) | 
    where("account_id"_c == 2)
  );

  if (!update_result2) {
    return false;
  }

  // Update account 3: set status to "active"
  auto update_result3 = update_result2.and_then(
    update<Account>("status"_c.set("active")) | 
    where("account_id"_c == 3)
  );

  if (!update_result3) {
    return false;
  }

  // Verify changes persisted by reading back the data
  auto read_result = update_result3.and_then(
    sqlgen::read<std::vector<Account>> | order_by("account_id"_c)
  );

  if (!read_result) {
    return false;
  }

  const auto& accounts = read_result.value();

  // Verify the updates
  if (accounts.size() != 3) {
    return false;
  }

  // Check account 1
  if (accounts[0].account_id.value() != 1 || 
      accounts[0].balance != 1500.0 || 
      accounts[0].status != "premium") {
    return false;
  }

  // Check account 2
  if (accounts[1].account_id.value() != 2 || 
      accounts[1].balance != 2500.0 || 
      accounts[1].status != "active") {
    return false;
  }

  // Check account 3
  if (accounts[2].account_id.value() != 3 || 
      accounts[2].balance != 1500.0 || 
      accounts[2].status != "active") {
    return false;
  }

  return true;
}

}  // namespace update_set_operations
