Looking at the code fragments and the requirements, I need to implement a FULL JOIN between Supplier and Product tables. Since SQLite doesn't natively support FULL OUTER JOIN, I'll need to simulate it using UNION of LEFT JOIN and RIGHT JOIN (or LEFT JOIN with a WHERE clause to get unmatched rows).

Here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>

namespace full_join_suppliers_products {

struct Supplier {
  sqlgen::PrimaryKey<int> supplier_id;
  std::string name;
};

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  int supplier_id;
  std::string name;
};

struct SupProd {
  std::string supplier_name;
  std::optional<std::string> product_name;
};

/**
 * Returns a vector of SupProd structs, where each struct contains the name of a supplier and the name of a product, if any.
 */
std::vector<SupProd> full_join_suppliers_products() {
  // Connect to SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite").value();

  std::vector<SupProd> results;

  // SQLite doesn't support FULL OUTER JOIN directly, so we simulate it with UNION
  // FULL JOIN = LEFT JOIN UNION RIGHT JOIN (excluding already matched rows)
  const std::string query = R"(
    SELECT s.name AS supplier_name, p.name AS product_name
    FROM Supplier s
    LEFT JOIN Product p ON s.supplier_id = p.supplier_id
    UNION
    SELECT s.name AS supplier_name, p.name AS product_name
    FROM Product p
    LEFT JOIN Supplier s ON p.supplier_id = s.supplier_id
    WHERE s.supplier_id IS NULL
  )";

  // Execute the query
  auto stmt_result = conn->prepare(query);
  if (!stmt_result) {
    return results;
  }

  auto stmt = std::move(*stmt_result);

  // Execute and iterate through results
  auto execute_result = stmt->execute();
  if (!execute_result) {
    return results;
  }

  while (stmt->step()) {
    SupProd row;

    // Get supplier_name (always present in our query)
    auto supplier_name = stmt->column_text(0);
    row.supplier_name = supplier_name ? std::string(supplier_name) : "";

    // Get product_name (may be NULL)
    auto product_name = stmt->column_text(1);
    if (product_name) {
      row.product_name = std::string(product_name);
    } else {
      row.product_name = std::nullopt;
    }

    results.push_back(std::move(row));
  }

  return results;
}

}  // namespace full_join_suppliers_products
```

This implementation:

1. **Connects to the database**: Uses `sqlgen::sqlite::connect()` to connect to "test_db.sqlite"
2. **Simulates FULL JOIN**: Since SQLite doesn't support FULL OUTER JOIN natively, it uses a UNION of:
   - LEFT JOIN to get all suppliers with their matching products
   - LEFT JOIN from Product to Supplier with a WHERE clause to get products without suppliers
3. **Returns joined results**: Collects all rows into a vector of `SupProd` structs
4. **Handles NULL values**: Uses `std::optional<std::string>` for product_name to handle cases where a supplier has no products

The query ensures all suppliers are included (even those without products) and all products are included (even those without matching suppliers), which satisfies the FULL JOIN requirement.

