    using namespace sqlgen::literals;

    // Construct DELETE query with complex conditions:
    // age < 18 OR status = 'inactive'
    const auto query = delete_from<User> 
        | where("age"_c < 18 || "status"_c == "inactive");

    // Generate and return the SQL string
    return sqlgen::sqlite::to_sql_string(query);
}

}  // namespace delete_with_complex_condition
