Looking at the code structure and the reference fragments, I need to implement the `get_top_products` function using the `sqlgen` library. Based on the examples and the SQL reference provided, here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace get_top_products {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string product_name;
  std::string category;
  double price;
};

struct Sales {
  sqlgen::PrimaryKey<int> sale_id;
  int product_id;
  int quantity;
  sqlgen::Date sale_date;
};

struct TopProduct {
  int product_id;
  std::string product_name;
  std::string category;
  double total_sales;
};

/**
 * Description: This function retrieves the top products based on total sales.
 * Returns: std::vector<TopProduct>.
 */
std::vector<TopProduct> get_top_products(size_t limit_count = 10) {
  // Connect to SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Build the SQL query
  std::string query = R"(
    SELECT 
      p.product_id,
      p.product_name,
      p.category,
      SUM(p.price * s.quantity) as total_sales
    FROM Product p
    INNER JOIN Sales s ON p.product_id = s.product_id
    GROUP BY p.product_id, p.product_name, p.category
    ORDER BY total_sales DESC
    LIMIT ?)";

  // Execute the query with the limit parameter
  auto stmt = conn->prepare(query);
  stmt->bind(1, static_cast<int>(limit_count));

  std::vector<TopProduct> results;

  // Iterate through the results
  while (stmt->step()) {
    TopProduct product;
    product.product_id = stmt->column_int(0);
    product.product_name = stmt->column_text(1);
    product.category = stmt->column_text(2);
    product.total_sales = stmt->column_double(3);
    results.push_back(product);
  }

  return results;
}

}  // namespace get_top_products
```

