Looking at the code fragments and the task requirements, I need to:

1. Use sqlgen to construct an UPDATE statement
2. Update the `score` column with arithmetic operation `score + 10`
3. Apply this to all players (no WHERE clause)
4. Return the generated SQL string

Based on the code fragments, I can see that sqlgen uses a `to_update` function and has a `to_sql` method. The key is to use the dynamic query building capabilities and express arithmetic operations.

Here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>

namespace update_with_arithmetic {

struct Player {
  sqlgen::PrimaryKey<int> id;
  int score;
};

/**
 * This function demonstrates updating a column with arithmetic.
 * Returns: std::string.
 */
inline std::string update_with_arithmetic() {
    // Create a dynamic update statement
    auto query = sqlgen::transpilation::to_update<Player>(
        rfl::make_named_tuple(
            rfl::field<"score">(sqlgen::dynamic::Arithmetic{
                sqlgen::dynamic::Column{.name = "score"},
                sqlgen::dynamic::ArithmeticOperator::Add,
                sqlgen::dynamic::Value{10}
            })
        ),
        std::nullopt  // No WHERE clause - update all players
    );

    // Convert to SQL string using SQLite dialect
    auto conn = sqlgen::sqlite::Connection::connect(":memory:");
    if (!conn) {
        return "";
    }

    return conn.value()->to_sql(query);
}

}  // namespace update_with_arithmetic
```

