Looking at the code structure and the reference fragments, I need to implement a function that:
1. Connects to SQLite database
2. Performs a JOIN query with temporal operations
3. Extracts date/time components and computes duration
4. Returns the results as a vector

Here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace project_time_tracking {

struct Project {
  sqlgen::PrimaryKey<int> project_id;
  std::string name;
};

struct TimeLog {
  sqlgen::PrimaryKey<int> log_id;
  int project_id;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> start_time;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> end_time;
};

struct TimeMetrics {
  sqlgen::PrimaryKey<int> project_id;
  std::string name;
  int day;
  int month;
  int year;
  int hour;
  int minute;
  int second;
  double duration_days;
};

/**
 * Description: This function tracks time metrics for each project, including day, month, year, hour, minute, second, and duration in days.
 * Returns: std::vector<TimeMetrics>.
 */
std::vector<TimeMetrics> project_time_tracking() {
  // Connect to SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Build the SQL query with temporal operations
  // SQLite uses strftime for date/time extraction and julianday for date differences
  const std::string query = R"(
    SELECT 
      p.project_id,
      p.name,
      CAST(strftime('%d', t.start_time) AS INTEGER) as day,
      CAST(strftime('%m', t.start_time) AS INTEGER) as month,
      CAST(strftime('%Y', t.start_time) AS INTEGER) as year,
      CAST(strftime('%H', t.start_time) AS INTEGER) as hour,
      CAST(strftime('%M', t.start_time) AS INTEGER) as minute,
      CAST(strftime('%S', t.start_time) AS INTEGER) as second,
      (julianday(t.end_time) - julianday(t.start_time)) as duration_days
    FROM Project p
    INNER JOIN TimeLog t ON p.project_id = t.project_id
  )";

  // Execute the query and read results
  auto result = conn->execute(query);

  std::vector<TimeMetrics> metrics;

  if (result) {
    // Iterate through the result set
    while (result->next()) {
      TimeMetrics metric;
      metric.project_id = result->get<int>(0);
      metric.name = result->get<std::string>(1);
      metric.day = result->get<int>(2);
      metric.month = result->get<int>(3);
      metric.year = result->get<int>(4);
      metric.hour = result->get<int>(5);
      metric.minute = result->get<int>(6);
      metric.second = result->get<int>(7);
      metric.duration_days = result->get<double>(8);

      metrics.push_back(metric);
    }
  }

  return metrics;
}

}  // namespace project_time_tracking
```

**Key implementation details:**

1. **Database Connection**: Uses `sqlgen::sqlite::connect()` to connect to "test_db.sqlite"

2. **Temporal Operations**: SQLite uses different functions than standard SQL:
   - `strftime('%d', ...)` for day extraction
   - `strftime('%m', ...)` for month
   - `strftime('%Y', ...)` for year
   - `strftime('%H', ...)` for hour
   - `strftime('%M', ...)` for minute
   - `strftime('%S', ...)` for second
   - `julianday()` difference for computing days between dates

3. **Query Execution**: Executes the raw SQL query and iterates through results

4. **Result Mapping**: Maps each row to a `TimeMetrics` struct and collects them in a vector

5. **Return Value**: Returns `std::vector<TimeMetrics>` containing all the time tracking data with extracted temporal components

