Based on the code fragments, particularly from `include/sqlgen/read.hpp`, I can see that `read_to_select_from` is a template function that takes `WhereType` and `LimitType` parameters.

Here's the complete file:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <sqlgen/transpilation/read_to_select_from.hpp>
#include <string>

namespace read_to_select_from_usage {

struct User {
  sqlgen::PrimaryKey<int> id;
  std::string name;
  int age;
};

/**
 * This function demonstrates using read_to_select_from.
 * Returns: std::string.
 */
inline std::string read_to_select_from_usage() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Create a WHERE clause: age > 18
  const auto where_clause = where("age"_c > 18);

  // Create a LIMIT clause: 10
  const auto limit_clause = limit(10);

  // Use read_to_select_from to generate the SQL query
  const auto query = transpilation::read_to_select_from<
      User,
      decltype(where_clause),
      transpilation::NoOrderBy,
      decltype(limit_clause)
  >(where_clause, limit_clause);

  return query;
}

}  // namespace read_to_select_from_usage
```

